"use strict";(self.webpackChunkwiki_en=self.webpackChunkwiki_en||[]).push([["93034"],{49506(e){e.exports=JSON.parse('{"tag":{"label":"Robotics","permalink":"/tags/robotics","allTagsPath":"/tags","count":6,"items":[{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J50/reComputer_Robotics_J501_Getting_Started","title":"Flash Jetpack && Interfaces Usage","description":"This wiki provides a comprehensive introduction to the hardware features and interface usage of the reComputer Jetson Robotics J501 carrier board. It covers detailed specifications, supported modules, setup instructions, and practical guides for using various interfaces such as dual M.2 Key M slots, 10GbE + 4x 1GbE Ethernet, USB 3.0, four CAN interfaces (2 native + 2 SPI-to-CAN), UART, DI/DO, I2S, and GMSL2 camera expansion, helping users quickly get started with robotics development on the J501 platform.","permalink":"/ai_robotics_recomputer_j501_robotics_getting_started"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/reComputer_Robotics_Getting_Started","title":"Getting Started with reComputer Robotics","description":"The reComputer Robotics J401 is a high-performance edge AI carrier board designed for advanced robotics applications. It supports NVIDIA Jetson Orin Nano and Orin NX modules in Super/MAXN mode, delivering up to 157 TOPS of AI computing power. The board offers extensive connectivity options, including dual Gigabit Ethernet, multiple USB 3.2 ports, CAN, M.2 slots for 5G/Wi-Fi/BT modules, and optional GMSL2 camera support. Pre-installed with JetPack 6, it ensures seamless deployment for robotics development. The rugged design supports wide operating temperatures and includes a pre-installed heatsink with fan. The setup involves flashing the JetPack OS onto an NVMe SSD using a compatible Ubuntu host PC, followed by hardware configuration and interface usage. Detailed hardware specifications, mechanical drawings, and technical resources are provided for developers, along with community and technical support channels for troubleshooting and discussion.","permalink":"/recomputer_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J401/Robotics_J401_carrierboard_Hardware_Interfaces_Usage","title":"Interfaces Usage","description":"This wiki provides a comprehensive introduction to the hardware features and interface usage of the reComputer Jetson Robotics J401 carrier board. It covers detailed specifications, supported modules, setup instructions, and practical guides for using various interfaces such as M.2, Ethernet, USB, CAN, UART, I2C, and GMSL2 camera expansion, helping users quickly get started with robotics development on the J401 platform.","permalink":"/recomputer_jetson_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J601/Robotics_J601_carrierboard_Hardware_Interfaces_Usage","title":"Interfaces Usage","description":"This wiki provides a comprehensive introduction to the hardware features and interface usage of the reComputer Jetson Robotics J601 carrier board. It covers detailed specifications, supported modules, setup instructions, and practical guides for using various interfaces such as M.2, Ethernet, USB, CAN, RS485/RS232, UART, I2C, I2S, GPIO, GMSL2 camera expansion, 5G, and GPS, helping users quickly get started with robotics development on the J601 platform.","permalink":"/recomputer_jetson_robotics_j601_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/J501_Mini/Robotics_J501_Mini_Hardware_Interfaces_Usage","title":"Mini J501 Flash JetPack and Interfaces Usage","description":"This wiki provides a comprehensive introduction to the hardware features and interface usage of the Jetson Mini J501 carrier board. Designed for edge AI and robotics scenarios, it covers detailed specifications, supported modules, setup instructions, and practical guides for using interfaces such as M.2, Ethernet, USB, CAN, UART, DI/DO, I2S, and GMSL2 camera expansion.","permalink":"/recomputer_j501_mini_getting_started"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/reComputer_Robotics_Hardware_Interfaces_Usage","title":"reComputer Robotics Hardware and Interfaces Usage","description":"This wiki provides a comprehensive introduction to the hardware features and interface usage of the reComputer Jetson Robotics J401 carrier board. It covers detailed specifications, supported modules, setup instructions, and practical guides for using various interfaces such as M.2, Ethernet, USB, CAN, UART, I2C, and GMSL2 camera expansion, helping users quickly get started with robotics development on the J401 platform.","permalink":"/recomputer_robotics_j401_hardware_interfaces_usage"}],"unlisted":false}}')}}]);